tma_getflag() { sed -n "s/^[[:space:]]*-[[:space:]]*\"\{0,1\}--$2=\([^\"]*\)\"\{0,1\}[[:space:]]*\$/\1/p" "$1" | tail -n 1; }
# tma_setflag FILE NAME VALUE ; empty VALUE deletes the flag
tma_setflag() {
  t="$(dirname "$1")/.tma.$$"; cp -p "$1" "$t" || return 1
  awk -v n="--$2" -v v="$3" '
  { L[NR]=$0 }
  END {
    pat="^[ \t]*-[ \t]*\"?" n "(=|\"?[ \t]*$)"; f=0; a=0
    for (i=1;i<=NR;i++) { if (L[i] ~ pat) f=i; if (!a && L[i] ~ /^[ \t]*-[ \t]*"?(kube-apiserver|kube-controller-manager|kube-scheduler|etcd)"?[ \t]*$/) a=i }
