    for (i=1;i<=NR;i++) {
      if (i==f) { ind=L[i]; sub(/-.*/,"",ind); if (v!="") print ind "- " n "=" v }
      else print L[i]
      if (!f && i==a) { ind=L[i]; sub(/-.*/,"",ind); if (v!="") print ind "- " n "=" v }
    }
  }' "$1" > "$t" && cat "$t" > "$1"; r=$?; rm -f "$t"
  [ $r -eq 0 ] || { echo "cannot edit args of $1 (no 'command:' list entry found); edit it manually" >&2; exit 1; }
