  if [ -z "$c" ]; then tma_setflag "$1" "$2" "$3"; else case ",$c," in *,"$3",*) ;; *) tma_setflag "$1" "$2" "$c,$3";; esac; fi; }
tma_setmin() { c=$(tma_getflag "$1" "$2"); case "$c" in ""|*[!0-9]*) tma_setflag "$1" "$2" "$3";; *) [ "$c" -ge "$3" ] || tma_setflag "$1" "$2" "$3";; esac; }
tma_authz() { c=$(tma_getflag "$1" authorization-mode); [ -n "$c" ] || c=Node,RBAC
  tma_setflag "$1" authorization-mode "$c"; tma_listdel "$1" authorization-mode AlwaysAllow
  tma_listadd "$1" authorization-mode Node; tma_listadd "$1" authorization-mode RBAC; }

